```c
#include <stdio.h>
#include <stdlib.h>

int exists(long long *pos, int n, long long val) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (pos[mid] == val) return 1;
        if (pos[mid] < val) lo = mid + 1;
        else hi = mid - 1;
    }
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *pos = (long long *)malloc((size_t)n * sizeof(long long));
    if (!pos) return 0;

    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long L;
        scanf("%lld", &L);
        pos[i] = total;
        total += L;
    }

    if (total % 2 != 0) {
        printf("N\n");
        free(pos);
        return 0;
    }

    long long target = total / 2;
    long long count = 0;

    for (int i = 0; i < n; i++) {
        long long want = pos[i] + target;
        if (want >= total) want -= total;
        if (exists(pos, n, want)) count++;
    }

    if (count >= 4) printf("S\n");
    else printf("N\n");

    free(pos);
    return 0;
}
```

